import FWCore.ParameterSet.Config as cms
from FWCore.ParameterSet.VarParsing import VarParsing
from Configuration.StandardSequences.Eras import eras
options=VarParsing('analysis')
options.register('manifest','mapping.json',VarParsing.multiplicity.singleton,VarParsing.varType.string,'Source mapping')
options.register('allowPartial',False,VarParsing.multiplicity.singleton,VarParsing.varType.bool,'Local limited-event checks only')
options.register('signalOnlyGenMatching',True,VarParsing.multiplicity.singleton,VarParsing.varType.bool,'Store PYTHIA GEN by default')
options.parseArguments()
process=cms.Process('GENQ',eras.Run3_2023)
process.load('FWCore.MessageService.MessageLogger_cfi')
process.MessageLogger.cerr.FwkReport.reportEvery=1000
process.options=cms.untracked.PSet(numberOfThreads=cms.untracked.uint32(1),numberOfStreams=cms.untracked.uint32(1),wantSummary=cms.untracked.bool(True))
process.maxEvents=cms.untracked.PSet(input=cms.untracked.int32(options.maxEvents))
process.source=cms.Source('PoolSource',fileNames=cms.untracked.vstring(options.inputFiles),duplicateCheckMode=cms.untracked.string('noDuplicateCheck'))
process.TFileService=cms.Service('TFileService',fileName=cms.string('d0_dstar_genq.root'),closeFileFast=cms.untracked.bool(True))
process.load('Configuration.StandardSequences.FrontierConditions_GlobalTag_cff')
process.GlobalTag.globaltag=cms.string('132X_mcRun3_2023_realistic_HI_v9')
process.GlobalTag.snapshotTime=cms.string('9999-12-31 23:59:59.000')
process.GlobalTag.toGet.extend([cms.PSet(record=cms.string('HeavyIonRcd'),tag=cms.string('CentralityTable_HFtowers200_HydjetDrum5F_Run3v1302x04_Official_MC'),connect=cms.string('frontier://FrontierProd/CMS_CONDITIONS'),label=cms.untracked.string('HFtowers'))])
process.load('RecoHI.HiCentralityAlgos.CentralityBin_cfi')
process.centralityBin.Centrality=cms.InputTag('hiCentrality')
process.centralityBin.centralityVariable=cms.string('HFtowers')
process.unpackedTracksAndVertices=cms.EDProducer('D0AuditTrackAndVertexUnpacker',packedCandidates=cms.VInputTag('packedPFCandidates','lostTracks',cms.InputTag('lostTracks','eleTracks')),packedCandidateNormChi2Map=cms.VInputTag('packedPFCandidateTrackChi2','lostTrackChi2',cms.InputTag('')),primaryVertices=cms.InputTag('offlineSlimmedPrimaryVertices'),secondaryVertices=cms.InputTag('slimmedSecondaryVertices'),recoverTracks=cms.bool(True))
from HLTrigger.HLTfilters.hltHighLevel_cfi import hltHighLevel
process.hltFilter=hltHighLevel.clone(andOr=cms.bool(True),throw=cms.bool(False),HLTPaths=cms.vstring('HLT_HIMinimumBiasHF1AND_v*','HLT_HIMinimumBiasHF1ANDZDC2nOR_v*','HLT_HIMinimumBiasHF1ANDZDC1nOR_v*'))
process.primaryVertexFilter=cms.EDFilter('VertexSelector',src=cms.InputTag('offlineSlimmedPrimaryVertices'),cut=cms.string('!isFake && abs(z) <= 25 && position.Rho <= 2'),filter=cms.bool(True))
process.clusterCompatibilityFilter=cms.EDFilter('D0AuditClusterFilter',cluscomSrc=cms.InputTag('hiClusterCompatibility'),minZ=cms.double(-20.),maxZ=cms.double(20.05),clusterPars=cms.vdouble(0.,.0045),nhitsTrunc=cms.int32(150),clusterTrunc=cms.double(2.))
process.phfCoincFilter2Th4=cms.EDFilter('D0AuditHFFilter',HFfilters=cms.InputTag('hiHFfilters','hiHFfilters'),threshold=cms.int32(4),minnumtowers=cms.int32(2))
process.load('RecoHI.HiEvtPlaneAlgos.HiEvtPlane_cfi')
process.hiEvtPlaneRecalc=process.hiEvtPlane.clone(trackTag=cms.InputTag('packedPFCandidates'),lostTag=cms.InputTag('lostTracks'),chi2MapTag=cms.InputTag('packedPFCandidateTrackChi2'),chi2MapLostTag=cms.InputTag('lostTrackChi2'),caloTag=cms.InputTag('particleFlow'),vertexTag=cms.InputTag('offlineSlimmedPrimaryVertices'),centralityVariable=cms.string('HFtowers'),centralityBinTag=cms.InputTag('centralityBin','HFtowers'),cutEra=cms.int32(0),minet=cms.double(.01),minpt=cms.double(.5),dzdzerror_pix=cms.double(40.),caloCentRef=cms.double(-1.),caloCentRefWidth=cms.double(-1.))
process.inputIndex=cms.EDProducer('GenQInputIndex')
process.genq=cms.EDAnalyzer('D0DstarGenQ',inputFile=cms.string(options.inputFiles[0] if len(options.inputFiles)==1 else ''),manifest=cms.string(options.manifest),summary=cms.string('summary.json'),allowPartial=cms.bool(options.allowPartial),signalOnlyGenMatching=cms.untracked.bool(options.signalOnlyGenMatching))
process.HLTSelection=cms.Path(process.hltFilter)
process.PVSelection=cms.Path(process.primaryVertexFilter)
process.ClusterSelection=cms.Path(process.clusterCompatibilityFilter)
process.HFSelection=cms.Path(process.phfCoincFilter2Th4)
process.QProduction=cms.Path(process.inputIndex*process.centralityBin*process.unpackedTracksAndVertices*process.hiEvtPlaneRecalc)
process.save=cms.EndPath(process.genq)
process.schedule=cms.Schedule(process.HLTSelection,process.PVSelection,process.ClusterSelection,process.HFSelection,process.QProduction,process.save)
